import {additionalQuestions} from './additional-questions.js';
import {questionMemoIds} from './memos.js';
export const topics = [
 ['values','Valeurs, textes et dates',15,5],['flow','Contrôle du flux',10,3],['objects','Programmation objet',30,10],['exceptions','Exceptions',10,3],['collections','Collections et génériques',15,5],['streams','Lambdas et streams',20,7],['modules','Modules et déploiement',15,5],['concurrency','Concurrence',15,5],['io','Entrées-sorties',12,4],['locale','Localisation',8,3]
].map(([id,name,count,exam])=>({id,name,count,exam}));
const API='https://docs.oracle.com/en/java/javase/21/docs/api/';
const JLS='https://docs.oracle.com/javase/specs/jls/se21/html/';
export const questions=[];
function q(topic,prompt,code,items,ref,check=null){
 const id=`${topic}-${String(questions.filter(q=>q.topic===topic).length+1).padStart(2,'0')}`;
 let options=items.map((s,i)=>{const [text,...rest]=s.replace(/^\+/, '').split(' ~ ');return {id:String(i),text,explanation:rest.join(' ~ '),correct:s.startsWith('+')};});
 const shift=questions.length%options.length; options=[...options.slice(shift),...options.slice(0,shift)];
 const tools={ 'modules-12':'https://docs.oracle.com/en/java/javase/21/docs/specs/man/jlink.html', 'modules-13':'https://docs.oracle.com/en/java/javase/21/docs/specs/man/jdeps.html' };
 questions.push({id,topic,prompt,code,options,memoId:questionMemoIds[id],required:options.filter(o=>o.correct).length,reference:tools[id]||(ref.startsWith('jls:')?JLS+ref.slice(4):API+ref),check});
}
function run(body,output){return {kind:'run',body,output};}
function fail(body){return {kind:'fail',body};}
const lang='jls:jls-5.html', str='java.base/java/lang/String.html', time='java.base/java/time/LocalDate.html';
q('values','Quel résultat est affiché ?', 'byte b = 127;\nb++;\nSystem.out.print(b);', ['+-128 ~ L’incrémentation inclut une conversion vers byte et déborde à -128.','128 ~ 128 dépasse la plage de byte.','Erreur de compilation ~ ++ est autorisé sur byte.','ArithmeticException ~ Le débordement entier ne lève pas cette exception.'],lang,run('byte b=127; b++; System.out.print(b);','-128'));
q('values','Que produit ce fragment ?', 'byte b = 1;\nb = b + 1;', ['+Erreur de compilation ~ b + 1 est promu en int ; l’affectation exige une conversion explicite.','b vaut 2 ~ Le calcul est possible mais pas cette affectation.','b vaut 1 ~ La compilation échoue avant toute exécution.','ClassCastException ~ Il s’agit d’une conversion primitive, pas d’un cast de références.'],lang,fail('byte b=1; b=b+1;'));
q('values','Quelle valeur est affichée ?', 'System.out.print(7 / 2 + 0.5);',['+3.5 ~ La division entière donne 3 avant l’addition avec un double.','4.0 ~ La division ne devient pas flottante rétroactivement.','3 ~ L’addition avec 0.5 produit un double.','Erreur de compilation ~ Les promotions numériques autorisent cette expression.'], 'jls:jls-15.html',run('System.out.print(7/2+0.5);','3.5'));
q('values','Quel résultat est affiché ?', 'int x = 3;\nboolean b = false && ++x > 3;\nSystem.out.print(x);',['+3 ~ && court-circuite son opérande droit quand le gauche vaut false.','4 ~ ++x n’est pas évalué ici.','false ~ Le programme affiche x, pas b.','Erreur de compilation ~ La comparaison produit bien un boolean.'],'jls:jls-15.html',run('int x=3; boolean b=false && ++x>3; System.out.print(x);','3'));
q('values','Quel résultat est affiché ?', 'String s = "java";\ns.toUpperCase();\nSystem.out.print(s);',['+java ~ String est immuable ; la nouvelle chaîne n’est pas affectée à s.','JAVA ~ toUpperCase ne modifie pas s.','Java ~ Cette méthode ne fait pas une capitalisation du premier caractère.','NullPointerException ~ s n’est pas null.'],str,run('String s="java"; s.toUpperCase(); System.out.print(s);','java'));
q('values','Quel résultat est affiché ?', 'System.out.print("A" + 1 + 2);',['+A12 ~ Les concaténations sont évaluées de gauche à droite.','A3 ~ Les nombres seraient additionnés dans "A" + (1 + 2).','68 ~ La chaîne empêche une addition purement numérique.','Erreur de compilation ~ La concaténation accepte les nombres.'],str,run('System.out.print("A"+1+2);','A12'));
q('values','Quel résultat est affiché ?', 'var b = new StringBuilder("abcd");\nb.delete(1, 3).reverse();\nSystem.out.print(b);',['+da ~ delete supprime les indices 1 et 2, puis reverse inverse ad.','dcb ~ La borne finale de delete est exclusive.','ad ~ reverse modifie le même builder.','Erreur de compilation ~ Les méthodes renvoient le builder pour permettre le chaînage.'],'java.base/java/lang/StringBuilder.html',run('var b=new StringBuilder("abcd"); b.delete(1,3).reverse(); System.out.print(b);','da'));
q('values','Quel résultat est affiché ?', 'Integer n = null;\nSystem.out.print(n + 1);',['+NullPointerException ~ L’addition impose un déballage de null.','1 ~ null n’est pas converti en zéro.','null1 ~ Il n’y a pas de String dans l’expression.','Erreur de compilation ~ Integer peut être déballé implicitement en int.'],lang,{kind:'throws',body:'Integer n=null; System.out.print(n+1);',exception:'NullPointerException'});
q('values','Quelle affirmation sur les text blocks est correcte ?', '', ['+Ils produisent des objets String ~ Un text block est un littéral de chaîne.','Ils sont modifiables ~ String reste immuable.','Ils désactivent toutes les séquences d’échappement ~ Des échappements comme \\n restent interprétés.','Ils nécessitent --enable-preview en Java 21 ~ Les text blocks sont une fonctionnalité standard.'],'jls:jls-3.html');
q('values','Quel résultat est affiché ?', 'var d = LocalDate.of(2024, 1, 31);\nSystem.out.print(d.plusMonths(1));',['+2024-02-29 ~ plusMonths ajuste au dernier jour valide de février, année bissextile.','2024-03-02 ~ L’API ne reporte pas les jours excédentaires en mars.','2024-02-31 ~ Cette date n’existe pas.','DateTimeException ~ L’ajustement est défini pour plusMonths.'],time,run('var d=LocalDate.of(2024,1,31); System.out.print(d.plusMonths(1));','2024-02-29'));
q('values','Quelle classe représente une quantité de temps en secondes et nanosecondes ?', '', ['+Duration ~ Duration est fondée sur le temps.','Period ~ Period représente des années, mois et jours.','LocalDate ~ LocalDate est une date sans heure.','ZoneId ~ ZoneId identifie des règles de fuseau horaire.'],'java.base/java/time/Duration.html');
q('values','Quel résultat est affiché ?', 'var p = Period.ofMonths(14);\nSystem.out.print(p.normalized());',['+P1Y2M ~ La normalisation répartit 14 mois en 1 an et 2 mois.','P14M ~ normalized effectue ici une transformation.','P1Y ~ Les 2 mois restants ne sont pas perdus.','P420D ~ Les mois ne sont pas convertis en un nombre fixe de jours.'],'java.base/java/time/Period.html',run('var p=Period.ofMonths(14); System.out.print(p.normalized());','P1Y2M'));
q('values','En Europe/Paris, que donne l’ajout d’un jour à midi la veille du passage à l’heure d’été du 31 mars 2024 ?', 'var z = ZonedDateTime.of(2024, 3, 30, 12, 0, 0, 0,\n    ZoneId.of("Europe/Paris"));\nSystem.out.print(Duration.between(z, z.plusDays(1)).toHours());',['+23 ~ plusDays conserve midi local ; le changement d’offset réduit la durée écoulée.','24 ~ Un jour calendaire n’est pas toujours une durée de 24 heures.','25 ~ Ce serait le sens du passage à l’heure d’hiver.','Erreur de compilation ~ Duration.between accepte ces objets temporels.'],'java.base/java/time/ZonedDateTime.html',run('var z=ZonedDateTime.of(2024,3,30,12,0,0,0,ZoneId.of("Europe/Paris")); System.out.print(Duration.between(z,z.plusDays(1)).toHours());','23'));
q('values','Quelles affirmations sont exactes ?', '', ['+Math.floor(-1.2) vaut -2.0 ~ floor arrondit vers l’infini négatif.','+Math.round(1.5) vaut 2L ~ La surcharge double renvoie un long, arrondi vers l’entier le plus proche avec égalité vers le haut.','Math.abs(Integer.MIN_VALUE) est positif ~ Cette valeur n’a pas d’opposé positif représentable en int.','Math.ceil(-1.2) vaut -2.0 ~ ceil arrondit vers l’infini positif et vaut -1.0.'],'java.base/java/lang/Math.html');
q('values','Quel résultat est affiché ?', 'System.out.print("certification".substring(4, 7));',['+ifi ~ substring inclut l’indice 4 et exclut l’indice 7.','ific ~ La borne 7 est exclusive.','tif ~ Le premier indice demandé est 4, pas 3.','IndexOutOfBoundsException ~ Les deux indices sont dans les limites autorisées.'],str,run('System.out.print("certification".substring(4,7));','ifi'));
q('flow','Quel résultat est affiché ?', 'int n = 2;\nString s = switch (n) {\n    case 1 -> "A";\n    case 2, 3 -> "B";\n    default -> "C";\n};\nSystem.out.print(s);',['+B ~ Les étiquettes 2 et 3 partagent la même branche.','BC ~ Une branche fléchée ne poursuit pas dans default.','C ~ Le case 2 correspond.','Erreur de compilation ~ Plusieurs constantes séparées par des virgules sont permises.'],'jls:jls-15.html',run('int n=2; String s=switch(n){case 1->"A";case 2,3->"B";default->"C";}; System.out.print(s);','B'));
q('flow','Quel résultat est affiché ?', 'int n = switch (2) {\n    case 2 -> { yield 7; }\n    default -> 0;\n};\nSystem.out.print(n);',['+7 ~ yield fournit la valeur du bloc de l’expression switch.','2 ~ Le sélecteur n’est pas la valeur de résultat.','0 ~ default n’est pas sélectionné.','Erreur de compilation ~ yield est valide dans ce bloc.'],'jls:jls-15.html',run('int n=switch(2){case 2->{yield 7;}default->0;}; System.out.print(n);','7'));
q('flow','Quel résultat est affiché ?', 'int n = 0;\nfor (int i = 0; i < 4; i++) {\n    if (i == 2) continue;\n    n += i;\n}\nSystem.out.print(n);',['+4 ~ La somme est 0 + 1 + 3 ; continue ne saute pas l’incrément.','6 ~ i=2 est exclu.','1 ~ continue ne termine pas la boucle.','Boucle infinie ~ L’incrément i++ est toujours exécuté après continue.'],'jls:jls-14.html',run('int n=0;for(int i=0;i<4;i++){if(i==2)continue;n+=i;}System.out.print(n);','4'));
q('flow','Quel résultat est affiché ?', 'int n = 0;\nouter: for (int i = 0; i < 3; i++) {\n    for (int j = 0; j < 3; j++) {\n        if (j == 1) break outer;\n        n++;\n    }\n}\nSystem.out.print(n);',['+1 ~ break outer quitte les deux boucles à i=0, j=1.','3 ~ Le label vise la boucle externe.','9 ~ Le break interrompt le parcours.','Erreur de compilation ~ Un break peut viser une boucle englobante étiquetée.'],'jls:jls-14.html',run('int n=0;outer:for(int i=0;i<3;i++){for(int j=0;j<3;j++){if(j==1)break outer;n++;}}System.out.print(n);','1'));
q('flow','Quel résultat est affiché ?', 'int n = 5;\ndo { n++; } while (n < 3);\nSystem.out.print(n);',['+6 ~ Le corps du do-while s’exécute au moins une fois.','5 ~ La condition est évaluée après le corps.','3 ~ La condition ne réaffecte pas n.','Boucle infinie ~ n < 3 est false dès la première évaluation.'],'jls:jls-14.html',run('int n=5;do{n++;}while(n<3);System.out.print(n);','6'));
q('flow','Que se passe-t-il ?', 'Object o = null;\nSystem.out.print(switch (o) {\n    case String s -> s;\n    default -> "autre";\n});',['+NullPointerException ~ default ne capture pas null ; un case null explicite serait nécessaire.','autre ~ default seul ne gère pas null.','null ~ Aucun case null ne fournit cette valeur.','Erreur de compilation ~ Un switch avec pattern sur Object est standard en Java 21.'],'jls:jls-14.html',{kind:'throws',body:'Object o=null; System.out.print(switch(o){case String s->s;default->"autre";});',exception:'NullPointerException'});
q('flow','Quel résultat est affiché ?', 'int n = 1;\nswitch (n) {\n    case 1: System.out.print("A");\n    case 2: System.out.print("B"); break;\n    default: System.out.print("C");\n}',['+AB ~ Les étiquettes avec deux-points autorisent la poursuite jusqu’au break.','A ~ Il manque un break après A.','ABC ~ Le break du case 2 empêche default.','Erreur de compilation ~ Ce switch statement classique est valide.'],'jls:jls-14.html',run('int n=1;switch(n){case 1:System.out.print("A");case 2:System.out.print("B");break;default:System.out.print("C");}','AB'));
q('flow','Quelle condition permet d’utiliser s dans le corps du if ?', '', ['+if (o instanceof String s && s.length() > 2) ~ && assure que le pattern a réussi avant d’évaluer la longueur.','if (o instanceof String s || s.length() > 2) ~ À droite de ||, le pattern peut avoir échoué et s n’est pas disponible.','if (o instanceof String s & s.length() > 2) ~ & ne garantit pas le flow scoping nécessaire à droite.','if (o instanceof String) ~ Ce test ne déclare aucune variable s.'],'jls:jls-6.html');
q('flow','Quelle propriété est requise pour une expression switch ?', '', ['+Elle doit être exhaustive ~ Toute valeur possible doit être couverte selon les règles du langage.','Elle doit toujours avoir un default explicite ~ Un enum ou une hiérarchie sealed peut permettre l’exhaustivité sans default.','Elle ne peut sélectionner qu’un int ~ Les String, enums et types de référence avec patterns sont aussi possibles.','Elle doit utiliser uniquement des flèches ~ Une expression switch peut utiliser des groupes avec deux-points et yield.'],'jls:jls-15.html');
q('flow','Quel résultat est affiché ?', 'int[] a = {1, 2};\nfor (int n : a) n *= 2;\nSystem.out.print(Arrays.toString(a));',['+[1, 2] ~ n est une variable locale contenant une copie de chaque entier.','[2, 4] ~ Réaffecter n ne modifie pas le tableau.','[1, 4] ~ Aucun élément n’est modifié.','Erreur de compilation ~ Une variable de boucle for-each peut être réaffectée si elle n’est pas final.'],'jls:jls-14.html',run('int[] a={1,2};for(int n:a)n*=2;System.out.print(Arrays.toString(a));','[1, 2]'));
const cls='jls:jls-8.html', itf='jls:jls-9.html';
q('objects','Quelles restrictions s’appliquent aux records ?', '', ['+Un record est implicitement final ~ Il ne peut pas avoir de sous-classe.','+Un record ne peut pas déclarer de champ d’instance supplémentaire ~ Son état d’instance est défini par ses composants.','Un record ne peut pas implémenter une interface ~ Il peut implémenter des interfaces.','Tous les composants d’un record sont profondément immuables ~ Une référence finale peut viser un objet mutable.'],cls);
q('objects','Quel accesseur est généré ?', 'record Point(int x, int y) {}',['+x() ~ L’accesseur porte le nom exact du composant.','getX() ~ La convention JavaBeans n’est pas utilisée par les records.','readX() ~ Aucun tel nom n’est généré.','x(int value) ~ Un record ne génère pas de setter.'],cls);
q('objects','Quel résultat est affiché ?', 'record P(int x) {}\nSystem.out.print(new P(2).equals(new P(2)));',['+true ~ equals généré compare le type du record et les composants.','false ~ Les identités diffèrent mais equals est redéfini.','2 ~ equals renvoie un boolean.','Erreur de compilation ~ Un record local est autorisé.'],cls,run('record P(int x){} System.out.print(new P(2).equals(new P(2)));','true'));
q('objects','Dans un constructeur compact de record, quelle instruction est autorisée ?', 'record Name(String value) {\n    Name { /* instruction */ }\n}',['+value = value.strip(); ~ Le paramètre peut être normalisé avant l’affectation implicite au champ.','this.value = value; ~ Un constructeur compact ne peut pas affecter explicitement les champs des composants.','return; ~ Un return explicite est interdit dans un constructeur compact.','super(); ~ Un constructeur compact ne commence pas par un appel explicite à super.'],cls);
q('objects','Quels modificateurs peuvent qualifier une sous-classe directe ordinaire d’une classe sealed ?', '', ['+final ~ Elle ferme sa propre branche d’héritage.','+non-sealed ~ Elle rouvre sa branche à l’héritage.','+sealed ~ Elle restreint à nouveau ses propres sous-types.','abstract seul ~ Une classe abstraite directe doit aussi être final, sealed ou non-sealed ; final est incompatible avec abstract.'],cls);
q('objects','Quel résultat est affiché ?', 'class A { String f() { return "A"; } }\nclass B extends A { String f() { return "B"; } }\nA a = new B();\nSystem.out.print(a.f());',['+B ~ La redéfinition des méthodes d’instance utilise le type réel.','A ~ Le type de référence ne choisit pas l’implémentation redéfinie.','AB ~ Une seule méthode est appelée.','Erreur de compilation ~ Une référence A peut viser une instance de B.'],cls,run('class A{String f(){return "A";}}class B extends A{String f(){return "B";}}A a=new B();System.out.print(a.f());','B'));
q('objects','Quel résultat est affiché ?', 'class A { int x = 1; }\nclass B extends A { int x = 2; }\nA a = new B();\nSystem.out.print(a.x);',['+1 ~ Les champs sont sélectionnés selon le type de référence.','2 ~ Les champs ne bénéficient pas du dispatch des méthodes d’instance.','3 ~ Les champs ne sont pas additionnés.','Erreur de compilation ~ Le masquage de champ est autorisé.'],cls,run('class A{int x=1;}class B extends A{int x=2;}A a=new B();System.out.print(a.x);','1'));
q('objects','Que doit respecter une méthode qui redéfinit une méthode public ?', '', ['+Elle doit rester public ~ L’accès ne peut pas être restreint.','Elle peut devenir protected ~ Cela réduit la visibilité.','Elle doit conserver exactement le type de retour de référence ~ Un retour covariant est autorisé.','Elle peut ajouter toute exception checked ~ Les exceptions checked ne peuvent pas être élargies librement.'],cls);
q('objects','Deux interfaces indépendantes déclarent la même méthode default. Que doit faire leur classe concrète commune ?', '', ['+Redéfinir la méthode pour résoudre le conflit ~ Deux defaults non hiérarchisés ne peuvent être hérités tels quels.','Choisir automatiquement la première interface de implements ~ L’ordre ne résout pas le conflit.','Hériter silencieusement des deux méthodes ~ L’appel serait ambigu et la compilation échoue.','Rendre nécessairement la classe final ~ final ne résout pas le conflit de méthodes.'],itf);
q('objects','Quelles méthodes sont possibles dans une interface Java 21 ?', '', ['+Une méthode private avec un corps ~ Elle peut mutualiser du code interne à l’interface.','+Une méthode static avec un corps ~ Elle s’appelle via le nom de l’interface.','Une méthode protected abstraite ~ protected n’est pas un accès autorisé ici.','Une méthode default sans corps ~ Une méthode default nécessite une implémentation.'],itf);
q('objects','Une interface déclare une méthode abstraite et redéclare boolean equals(Object). Est-elle fonctionnelle ?', '', ['+Oui, si les autres règles sont respectées ~ Une méthode publique correspondant à Object ne compte pas dans le contrat fonctionnel.','Non, elle a toujours deux méthodes fonctionnelles ~ equals correspondant à Object est exclue du comptage.','Seulement avec @FunctionalInterface ~ L’annotation vérifie le contrat mais ne le crée pas.','Seulement si elle ne contient aucun default ~ Des defaults sont compatibles avec une interface fonctionnelle.'],itf);
q('objects','Quel appel sélectionne f(long) plutôt que f(Integer) ?', 'static void f(long x) {}\nstatic void f(Integer x) {}',['+f(1) ~ L’élargissement primitif est préféré au boxing.','f(Integer.valueOf(1)) ~ La surcharge Integer est une correspondance directe.','f((Integer) null) ~ Le type Integer sélectionne sa surcharge.','f(null) ~ null est applicable à Integer, pas à long.'],'jls:jls-15.html');
q('objects','Quelle déclaration var est valide dans une méthode ?', '', ['+var names = new ArrayList<String>(); ~ L’initialiseur permet d’inférer le type local.','var value = null; ~ null ne permet pas d’inférer un type utile.','var x; ~ Un initialiseur est requis pour cette variable locale.','var a = 1, b = 2; ~ var n’autorise pas plusieurs déclarateurs dans la même déclaration.'],'jls:jls-14.html');
q('objects','Que se passe-t-il lors de ce cast ?', 'Object o = "Java";\nInteger n = (Integer) o;',['+ClassCastException ~ Le type réel String n’est pas compatible avec Integer.','Erreur de compilation ~ Le type statique Object autorise le cast explicite vers Integer.','n vaut null ~ Un cast incorrect ne renvoie pas null.','n vaut 0 ~ Un cast de référence ne convertit pas le contenu d’une chaîne.'],'jls:jls-5.html',{kind:'throws',body:'Object o="Java"; Integer n=(Integer)o;',exception:'ClassCastException'});
q('objects','Quel résultat est affiché ?', 'Object o = "abc";\nif (o instanceof String s) System.out.print(s.length());',['+3 ~ Le pattern vérifie le type et lie s à la chaîne.','true ~ Le code affiche la longueur, pas le test.','abc ~ Le code appelle length.','Erreur de compilation ~ Le pattern instanceof est standard en Java 21.'],'jls:jls-15.html',run('Object o="abc";if(o instanceof String s)System.out.print(s.length());','3'));
q('objects','Quel résultat est affiché ?', 'record P(int x, int y) {}\nObject o = new P(2, 3);\nif (o instanceof P(int x, int y)) System.out.print(x + y);',['+5 ~ Le record pattern décompose les composants.','23 ~ Les deux variables sont des int.','false ~ Le pattern correspond au record P.','Erreur de compilation ~ Les record patterns sont standard en Java 21.'],'jls:jls-14.html',run('record P(int x,int y){}Object o=new P(2,3);if(o instanceof P(int x,int y))System.out.print(x+y);','5'));
q('objects','Quelle branche doit précéder case String s dans un switch sur Object ?', '', ['+case String s when s.isEmpty() ~ Le pattern gardé plus spécifique doit précéder le pattern non gardé.','case Object x ~ Ce pattern dominerait le pattern String suivant.','default doit toujours être premier ~ default n’a pas cette obligation.','case String s when true doit précéder tout autre String ~ Un garde constant true ne rend pas le pattern plus spécifique.'],'jls:jls-14.html');
q('objects','Quelle déclaration de constructeur est correcte pour un enum ?', '', ['+Un constructeur sans modificateur d’accès ~ Il est implicitement private.','Un constructeur public ~ Les constructeurs d’enum ne peuvent pas être public.','Un constructeur protected ~ protected est interdit pour un constructeur d’enum.','Un constructeur abstract ~ Les constructeurs ne peuvent pas être abstract.'],cls);
q('objects','Quelle affirmation sur les constantes d’un enum est exacte ?', '', ['+Elles peuvent avoir chacune un corps de classe ~ Une constante peut fournir une implémentation spécifique.','Elles sont créées avec new dans le code client ~ Une enum ne s’instancie pas explicitement ainsi.','Elles sont comparables uniquement avec equals ~ == est adapté aux constantes enum.','Elles sont recréées à chaque appel de values() ~ values renvoie un tableau contenant les constantes existantes.'],cls);
q('objects','Quelle règle concerne une classe interne membre non static ?', '', ['+Son instance est associée à une instance englobante ~ Une instance externe est nécessaire pour sa création normale.','Elle ne peut jamais accéder aux membres privés externes ~ L’accès lexical aux membres privés est permis.','Elle est toujours implicitement static ~ C’est le cas des classes imbriquées static, pas de cette classe interne.','Elle ne peut avoir aucun membre static en Java 21 ~ Cette restriction ancienne n’est plus générale.'],cls);
q('objects','Que peut capturer une classe locale depuis la méthode englobante ?', '', ['+Une variable locale final ou effectivement final ~ Sa valeur ne doit pas être réaffectée.','Toute variable locale réaffectée ensuite ~ Une telle variable n’est pas effectivement final.','Seulement les types primitifs ~ Les références sont aussi capturables.','Seulement les paramètres annotés @Deprecated ~ Cette annotation ne contrôle pas la capture.'],'jls:jls-6.html');
q('objects','Après a = null, que garantit Java concernant l’objet anciennement référencé par a ?', 'Object a = new Object();\na = null;',['+Aucune collecte immédiate n’est garantie ~ L’absence de référence accessible rend l’objet éligible, sans imposer une date de collecte.','Il est détruit immédiatement ~ Java ne garantit pas une destruction immédiate.','System.gc() garantirait sa collecte ~ Cet appel reste une demande, pas une garantie.','Son adresse mémoire reste disponible dans a ~ a contient désormais null.'],'jls:jls-12.html');
q('objects','Quelle mesure protège une classe immuable contenant une List mutable fournie au constructeur ?', '', ['+Stocker une copie non modifiable et maîtriser les éléments mutables ~ La référence final seule ne suffit pas à protéger le contenu.','Déclarer uniquement le champ final ~ La liste peut rester modifiable par un alias.','Retourner directement la liste interne mutable ~ Cela expose l’état interne.','Ajouter un setter synchronisé ~ Un setter change l’état et n’assure pas l’immuabilité.'],cls);
q('objects','Quel résultat est affiché ?', 'class A {\n    int n = 2;\n    { n++; }\n    A() { n *= 2; }\n}\nSystem.out.print(new A().n);',['+6 ~ Le champ est initialisé, puis le bloc d’instance, puis le corps du constructeur.','5 ~ Le constructeur ne précède pas le bloc d’instance.','4 ~ Le bloc d’instance participe à l’initialisation.','2 ~ Le constructeur et le bloc sont exécutés.'],'jls:jls-12.html',run('class A{int n=2;{n++;}A(){n*=2;}}System.out.print(new A().n);','6'));
q('objects','Une classe ne déclare aucun constructeur. Que génère le compilateur ?', '', ['+Un constructeur par défaut dont l’accès suit celui de la classe ~ Il invoque notamment le constructeur sans argument de la superclasse.','Toujours un constructeur public ~ Une classe non publique n’a pas forcément un constructeur public.','Un constructeur pour chaque champ ~ Ce n’est pas le comportement des classes ordinaires.','Aucun constructeur ~ Un constructeur par défaut est fourni pour une classe ordinaire sans constructeur déclaré.'],cls);
q('objects','Quelle règle s’applique à un paramètre varargs ?', '', ['+Il doit être le dernier paramètre ~ Les paramètres fixes précèdent l’argument variable.','Il peut être répété deux fois ~ Un seul paramètre varargs est possible.','Il ne peut recevoir un tableau explicite ~ Un tableau du type adéquat est accepté.','Il garantit au moins un argument ~ Zéro argument variable est permis.'],cls);
q('objects','Quelles affirmations sur equals et hashCode sont exactes ?', '', ['+Deux objets égaux doivent avoir le même hashCode ~ C’est une obligation du contrat.','+Deux objets de même hashCode peuvent être différents ~ Les collisions sont autorisées.','Deux objets de même hashCode sont nécessairement égaux ~ Le contrat n’impose pas la réciproque.','equals doit comparer uniquement les identités ~ Une égalité de valeur est possible.'],'java.base/java/lang/Object.html');
q('objects','À quoi sert @Override ?', '', ['+À faire vérifier la redéfinition ou l’implémentation par le compilateur ~ Une signature incorrecte est détectée.','À rendre une méthode virtuelle ~ Les méthodes d’instance redéfinissables le sont sans cette annotation.','À autoriser la redéfinition de final ~ final reste non redéfinissable.','À supprimer toute erreur de type ~ L’annotation ajoute une vérification ciblée.'],'java.base/java/lang/Override.html');
q('objects','Quelle affirmation sur @SafeVarargs est correcte ?', '', ['+Elle peut annoter un constructeur varargs ~ Elle atteste un usage sûr des arguments variables non réifiables.','Elle peut annoter toute méthode d’instance redéfinissable ~ Les méthodes concernées doivent être static, final ou private.','Elle transforme le tableau varargs en collection immuable ~ Elle ne transforme pas les données.','Elle supprime les vérifications de type à l’exécution ~ Elle ne change pas la sémantique d’exécution.'],'java.base/java/lang/SafeVarargs.html');
q('objects','Quel résultat est affiché ?', 'class A { static String f() { return "A"; } }\nclass B extends A { static String f() { return "B"; } }\nA a = new B();\nSystem.out.print(a.f());',['+A ~ Une méthode static est masquée et sélectionnée selon le type statique.','B ~ Il n’y a pas de dispatch dynamique pour static.','AB ~ Un seul appel est réalisé.','Erreur de compilation ~ L’appel via une instance est permis, bien que déconseillé.'],cls,run('class A{static String f(){return "A";}}class B extends A{static String f(){return "B";}}A a=new B();System.out.print(a.f());','A'));
