q('streams','Quel résultat est affiché ?', 'System.out.print(Stream.iterate(1, n -> n + 1)\n    .limit(4).dropWhile(n -> n < 3).toList());',['+[3, 4] ~ Le préfixe 1, 2 est retiré après limitation à quatre éléments.','[1, 2] ~ Ce serait le préfixe conservé par takeWhile.','[4] ~ La condition cesse d’être vraie à 3, qui est conservé.','Boucle infinie ~ limit borne le pipeline.'],stream,run('System.out.print(Stream.iterate(1,n->n+1).limit(4).dropWhile(n->n<3).toList());','[3, 4]'));
